module pizza_delivery_optimizer (\n    input clk,\n    input rst_n,\n    input start,\n    input [3:0] n,\n    input [3:0] m,\n    input [3:0] k,\n    input [3:0] edge_u [0:15],\n    input [3:0] edge_v [0:15],\n    input [31:0] edge_d [0:15],\n    input [31:0] order_s [0:7],\n    input [3:0] order_u [0:7],\n    input [31:0] order_t [0:7],\n    output reg [31:0] result,\n    output reg done\n);\n\n    // State definitions with explicit width\n    localparam [2:0] IDLE = 3'd0;\n    localparam [2:0] INIT_DIST = 3'd1;\n    localparam [2:0] FLOYD_UPDATE = 3'd2;\n    localparam [2:0] COMPUTE_DELIVERY = 3'd3;\n    localparam [2:0] DONE = 3'd4;\n\n    reg [2:0] state;\n    reg [3:0] i_cnt, j_cnt, k_cnt;\n    reg [31:0] dist [0:7][0:7];\n    reg [31:0] D_prev, D_curr, T_min;\n    reg [3:0] order_idx;\n\n    // Constants\n    localparam [31:0] INF = 32'h7FFFFFFF;\n\n    integer i, j;  // For loop variables\n\n    always @(posedge clk or negedge rst_n) begin\n        if (!rst_n) begin\n            state <= IDLE;\n            done <= 1'b0;\n            result <= 32'd0;\n            i_cnt <= 4'd0;\n            j_cnt <= 4'd0;\n            k_cnt <= 4'd0;\n            order_idx <= 4'd0;\n            D_prev <= 32'd0;\n            D_curr <= 32'd0;\n            T_min <= 32'd0;\n            \n            // Initialize dist array\n            for (i = 0; i < 8; i = i + 1) begin\n                for (j = 0; j < 8; j = j + 1) begin\n                    dist[i][j] <= (i == j) ? 32'd0 : INF;\n                end\n            end\n        end else begin\n            case (state)\n                IDLE: begin\n                    done <= 1'b0;\n                    if (start) begin\n                        state <= INIT_DIST;\n                        i_cnt <= 4'd0;\n                        j_cnt <= 4'd0;\n                    end\n                end\n\n                INIT_DIST: begin\n                    if (i_cnt < m) begin\n                        if (edge_u[i_cnt] < n && edge_v[i_cnt] < n) begin\n                            dist[edge_u[i_cnt]-1][edge_v[i_cnt]-1] <= edge_d[i_cnt];\n                            dist[edge_v[i_cnt]-1][edge_u[i_cnt]-1] <= edge_d[i_cnt];\n                        end\n                        i_cnt <= i_cnt + 4'd1;\n                    end else begin\n                        i_cnt <= 4'd0;\n                        k_cnt <= 4'd0;\n                        state <= FLOYD_UPDATE;\n                    end\n                end\n\n                FLOYD_UPDATE: begin\n                    if (k_cnt < n) begin\n                        if (i_cnt < n) begin\n                            if (j_cnt < n) begin\n                                if (dist[i_cnt][k_cnt] != INF && dist[k_cnt][j_cnt] != INF) begin\n                                    if (dist[i_cnt][k_cnt] + dist[k_cnt][j_cnt] < dist[i_cnt][j_cnt]) begin\n                                        dist[i_cnt][j_cnt] <= dist[i_cnt][k_cnt] + dist[k_cnt][j_cnt];\n                                    end\n                                end\n                                j_cnt <= j_cnt + 4'd1;\n                            end else begin\n                                j_cnt <= 4'd0;\n                                i_cnt <= i_cnt + 4'd1;\n                            end\n                        end else begin\n                            i_cnt <= 4'd0;\n                            k_cnt <= k_cnt + 4'd1;\n                        end\n                    end else begin\n                        state <= COMPUTE_DELIVERY;\n                        order_idx <= 4'd0;\n                    end\n                end\n\n                COMPUTE_DELIVERY: begin\n                    if (order_idx < k) begin\n                        if (order_idx == 0) begin\n                            if (order_u[0] > 0 && order_u[0] <= n) begin\n                                reg [31:0] first_dist = dist[0][order_u[0]-1];\n                                if (first_dist > order_t[0]) begin\n                                    D_prev <= first_dist;\n                                    T_min <= first_dist - order_s[0];\n                                end else begin\n                                    D_prev <= order_t[0];\n                                    T_min <= order_t[0] - order_s[0];\n                                end\n                            end\n                            order_idx <= order_idx + 4'd1;\n                        end else begin\n                            if (order_u[order_idx-1] <= n && order_u[order_idx] <= n) begin\n                                reg [31:0] travel_time = dist[order_u[order_idx-1]-1][order_u[order_idx]-1];\n                                reg [31:0] arrival_time = D_prev + travel_time;\n                                reg [31:0] new_T;\n                                reg [31:0] candidate_time;\n\n                                if (arrival_time > order_t[order_idx]) candidate_time = arrival_time;\n                                else candidate_time = order_t[order_idx];\n\n                                new_T = candidate_time - order_s[order_idx];\n                                if (new_T > T_min) T_min <= new_T;\n\n                                D_prev <= candidate_time;\n                            end\n                            order_idx <= order_idx + 4'd1;\n                        end\n                    end else begin\n                        result <= T_min;\n                        state <= DONE;\n                        done <= 1'b1;\n                    end\n                end\n\n                DONE: begin\n                    done <= 1'b0;\n                    state <= IDLE;\n                end\n\n                default: state <= IDLE;\n            endcase\n        end\n    end\nendmodule